<section class="panel portal-profile" id="profile"><div class="panel-head"><div><h2>Company profile</h2><p>Update your authorised contact and addresses</p></div><a href="<?= url('account/password') ?>">Change password</a></div><form class="mini-form" method="post" action="<?= url('portal/client/profile') ?>"><?= csrf_field() ?><div class="form-grid"><label>Primary contact<input name="primary_contact" value="<?= e($client['primary_contact']) ?>" required maxlength="150"></label><label>Phone<input name="phone" value="<?= e($client['phone']) ?>" required maxlength="30"></label><label>City<input name="city" value="<?= e($client['city']) ?>" maxlength="100"></label><label>State<input name="state" value="<?= e($client['state']) ?>" maxlength="100"></label><label class="wide">Billing address<textarea name="billing_address" rows="3"><?= e($client['billing_address']) ?></textarea></label><label class="wide">Service address<textarea name="service_address" rows="3"><?= e($client['service_address']) ?></textarea></label></div><button class="button button-primary button-sm">Save company profile</button></form></section>
